INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210323, 101196, '2914ba68-d865-5196-ad0d-893256c22cc9', NULL, 'Evening light is when my family actually lives. Kids'' soccer, grilling, walks after dinner, all of it dies an hour earlier under permanent standard time. The people pushing standard time are optimizing for sleep labs, not real evenings.', 'agree', 5, '2026-09-24 12:38:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210325, 101194, '8139a50e-240b-551e-85f5-ec8b818d23be', NULL, 'As a teacher, the week after each change is lost instructional time. Tired kids do not learn, and no lesson plan survives a room full of jet-lagged eight-year-olds. End the switching and give us the week back.', 'strongly_agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210326, 101197, '63413976-38af-50d5-9354-2b535ac4e9d4', NULL, 'I am skeptical of the crime numbers. Crime correlates with temperature, foot traffic, and a dozen other things that change with the seasons. Attributing drops to the clock specifically feels like advocacy dressed as research.', 'disagree', 3, '2026-09-24 13:52:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210327, 101198, 'fa765893-7275-5eea-a263-a68aacd27d16', NULL, 'The 1974 experiment is the part everyone forgets. We tried year-round daylight time, parents hated the dark school mornings, and it lasted one winter. Whoever picks the replacement time should have to explain why this time is different.', 'neutral', 7, '2026-09-24 11:50:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210328, 101195, 'fefd71d9-2772-5fd9-8799-eb4c420bd194', NULL, 'I work rotating shifts and the timecard mess described here is real. Our payroll system double-counts the fall-back hour every single year and someone has to fix it by hand. Multiply that by every employer in America.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210331, 101199, '9bafda97-6949-58cd-abd2-1696b1e9c306', NULL, 'The long tail point is exactly right. Everyone knows the big names, but the flashlight app with 50,000 downloads selling location pings is the one tracking my kid''s walk to school. Automatic audits are the only thing that reaches those companies.', 'strongly_agree', 0, '2026-09-23 19:57:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210333, 101200, '6a8c57ce-0e94-52e0-8aa7-3783561987a2', NULL, 'The auditor shortage is a genuine bottleneck. We already see it in financial audits, where a handful of firms dominate. Mandate audits for every location violation and you create a seller''s market that big tech will simply buy up.', 'agree', 4, '2026-09-23 21:09:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210335, 101199, '10625523-a431-5678-888f-8127f2e8c8eb', NULL, 'I like the deterrent effect but worry about checkbox audits. An auditor who depends on repeat business has every incentive to find the paperwork in order. Independence needs real teeth behind it.', 'neutral', 7, '2026-09-23 20:45:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210336, 101200, 'bb708620-1c6d-50d3-b168-cdc7570a1c9f', NULL, 'Strongly disagree that audits are the answer at all. You cannot audit back data that was already sold to brokers. Ban the sale of precise location data outright and the audit question becomes moot.', 'strongly_disagree', 8, '2026-09-23 20:26:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210339, 101201, 'a50e13cf-78a7-5092-8a1a-a13fc4738307', NULL, 'Regulatory arbitrage is the whole game. Companies already shop for the friendliest data regime, and AI labs will do the same with safety rules. A voluntary principle that a lab can dodge by moving servers is not a rule at all.', 'strongly_agree', 4, '2026-09-24 04:42:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210341, 101202, '21a2419c-bbf8-5db4-8704-804f55e768d1', NULL, 'The lowest-common-denominator risk is real. A global standard negotiated with 190 countries will be weak by design, and then industry will wave it around to block stronger national laws. We have seen this movie with climate accords.', 'agree', 1, '2026-09-23 19:27:35+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210343, 101201, 'cea365c4-bd89-569f-b75d-371fa108b5e2', NULL, 'I keep going back and forth. Enforcement without a real enforcer is fantasy, but voluntary norms have a decent record of hardening into law once best practices settle. Maybe sequence it: norms now, binding rules later.', 'neutral', 6, '2026-09-24 02:41:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210344, 101202, '35fc21d5-96f1-547f-b87b-d551077f2fee', NULL, 'Strongly disagree with the premise that binding global tech rules are even possible. There is no world government, no global court with teeth here, and pretending otherwise just launders power to whoever writes the draft.', 'strongly_disagree', 1, '2026-09-23 19:43:35+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210347, 101203, '2336fb05-0e39-5cf2-8b0f-2437b4583c24', NULL, 'The sponsorship flywheel is the argument that finally makes the commercial case. Brands cannot sponsor audiences that broadcasters hide. Put the milestones in prime time, show the ratings, and the money follows.', 'strongly_agree', 8, '2026-09-24 02:11:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210349, 101204, '86f5f5f8-40f8-5728-9eee-d227ccd858fe', NULL, 'Rights contracts are the boring reality nobody wants to discuss. Prime-time inventory is sold years ahead with legal guarantees. A mandate would spend its first three years in court, which helps nobody.', 'agree', 8, '2026-09-23 17:26:54+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210351, 101203, 'b96fbabd-1f85-5756-bd4d-0e9aaca3f7e6', NULL, 'Both the money argument and the contract argument are true, which is awkward. The flywheel works, but mandates are clumsy. Maybe the pressure should be on sponsors to demand the slots rather than on regulators.', 'neutral', 1, '2026-09-24 01:02:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210352, 101204, '414dd639-b232-5e30-ab1a-c764c88c747f', NULL, 'Strongly disagree that mandates help here. Forced promotion reads as charity no matter the intent, and charity framing is poison for a sport trying to prove its commercial worth. Earn the slot, do not legislate it.', 'strongly_disagree', 6, '2026-09-23 18:22:54+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210355, 101205, '9778618a-eecd-5dfb-bda6-485db1214b50', NULL, 'The preventive medicine framing is exactly how treasuries think. Every pound spent keeping people active is pounds not spent on cardiac wards. Funding formulas that ignore that are bad accounting, not high standards.', 'strongly_agree', 2, '2026-09-23 22:28:55+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210357, 101206, '1ae45afe-38c4-5a65-bb14-7fc040017685', NULL, 'The double-counting point is underappreciated. Schools, councils, and health agencies already fund participation. Elite money is the only stream that can produce a gold medal, so diluting it means funding everything and achieving nothing.', 'agree', 0, '2026-09-23 22:20:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210359, 101205, 'a0a29f33-17de-52dd-8dbe-f5f2cb5cb454', NULL, 'Health savings get exaggerated by advocates. The people who take up funded sport are mostly already active; the truly sedentary rarely join programs. The return-on-investment math is softer than it looks.', 'disagree', 1, '2026-09-23 20:46:55+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210360, 101206, '343e405d-1ea6-56c2-b5e2-e1fb9a0945a8', NULL, 'Strongly disagree with mixing the missions at all. Elite sport and public health are different jobs with different measures. A swimmer chasing Olympic trials should not have funding depend on how many beginners joined a learn-to-swim class.', 'strongly_disagree', 0, '2026-09-23 19:45:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210363, 101207, '7cd5a514-8890-5913-b05b-ec8e5bd9d7ab', NULL, 'The legal bill argument is the sleeper here. Federations have burned millions on equal-pay litigation that a clear standard would have avoided. Standardization is cheaper than the lawyers.', 'strongly_agree', 7, '2026-09-23 16:10:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210365, 101208, '520fe1cd-e8be-5378-a5e9-ded5b425933e', NULL, 'The tennis point is the one standardization fans never answer. When the women''s event outdraws the men''s, a unisex schedule caps the women. Equality should mean equal opportunity to earn, not identical checks regardless of economics.', 'agree', 5, '2026-09-24 07:59:01+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210367, 101207, '69956da6-25af-5140-bdf1-e7ef53f276c3', NULL, 'I see the appeal of simplicity, but records genuinely differ in commercial value. A world record in the 100 meters is not the same product as a world record in race walking. Some judgment will always be needed.', 'neutral', 7, '2026-09-23 18:51:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210368, 101208, 'ffe71cf0-e68c-5513-8d7f-db5ad04d7846', NULL, 'Strongly disagree that one schedule fits all. Sports have different seasons, different sponsors, different audiences. Centralized bonus tables are bureaucracy, and bureaucracy always lags reality.', 'strongly_disagree', 6, '2026-09-24 06:53:01+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210371, 101209, '4a8f4a7e-c9c8-5980-91d6-bb07f645fc75', NULL, 'The chip supply chain point is the strongest technical argument for this whole idea. You cannot hide a gigawatt data center. Compute verification gives inspectors something real to count, unlike model weights.', 'strongly_agree', 5, '2026-09-23 20:05:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210373, 101210, '3debd55c-ef91-5778-b13e-72a4ca48bd9b', NULL, 'The toothless-or-captured dilemma is the core problem. A voluntary club gets ignored by the racers, and a mandatory regime gets vetoed by the great powers. Either way the institution serves its funders, not the public.', 'agree', 6, '2026-09-23 16:21:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210375, 101209, '38fea548-c1e9-55cb-8386-000018da5b31', NULL, 'Compute monitoring is technically plausible but politically fraught. Metering a country''s data centers is the kind of surveillance great powers will never accept on themselves, even if they demand it of others.', 'neutral', 1, '2026-09-23 20:44:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210376, 101210, 'd1e61595-e39e-548a-9fda-cc5c82c37c67', NULL, 'Strongly disagree that authority is even desirable. Centralized control over AI development is a single point of failure and a prize for whoever captures it. Distributed safety research beats one global gatekeeper.', 'strongly_disagree', 6, '2026-09-23 16:50:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210002, 101001, 'a5e48176-d13e-56cd-9d5d-bf0677be0202', 210001, 'Exactly. And the platforms know when a filter is applied because they built the filter. This would cost them almost nothing to implement automatically.', 'agree', 8, '2026-09-23 13:52:12+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210004, 101004, '4ff27a04-8893-56ed-becd-a17274f513be', 210003, 'This is the part supporters keep dodging. A $20,000 camera and studio lighting alters a face more than any phone filter, and none of that gets a label. The rule targets the tool poor creators use.', 'strongly_agree', 7, '2026-09-23 23:26:53+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210007, 101005, '0b69664d-8df3-5463-8381-752528cfc3ad', 210006, 'But strictly paid product claims are already covered by false advertising law in the US. The FTC can already go after deceptive before-and-afters. We do not need a new filter-specific statute for something the old law reaches.', 'disagree', 8, '2026-09-23 16:45:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210009, 101003, '1bcf61ee-325a-573f-a2b9-0eee4134e83c', 210008, 'I do not buy that. The French law has been in force since 2023 and I have not seen small creators getting crushed by it. The fear is bigger than the enforcement reality.', 'disagree', 4, '2026-09-24 04:56:41+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210012, 101007, '3f05cd81-2847-5180-aef0-4a33d663106b', 210011, 'And the FAO number is doing a lot of quiet work here: 14.5 percent is bigger than all of transport. We obsess over electric cars while ignoring the bigger slice.', 'agree', 7, '2026-09-24 02:18:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210014, 101010, '438c0cb2-6fb7-5f66-b9cc-65d21fcb485a', 210013, 'Exactly. Every one of these proposals is written by people who shop at farmers markets. Tell a single mom the chicken is doubling for the planet and watch how fast she stops listening.', 'strongly_agree', 8, '2026-09-23 18:08:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210016, 101008, '40b238fa-bd6d-5a06-a1a7-cb911ae9b424', 210015, 'It is both, though. The CDC tracks agricultural use as a real contributor. Saying hospitals are worse does not make farm overuse fine.', 'disagree', 7, '2026-09-23 13:19:07+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210020, 101009, '97ea22ad-9076-59b5-832d-cb1b9a53ab3b', 210019, 'That is a fair criticism of one state''s rule, but a national phaseout is a different animal. You cannot route around a federal ban the way you route around California.', 'neutral', 7, '2026-09-23 21:39:49+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210022, 101013, '07f9f315-a1d3-5796-87e9-7a8d490e2130', 210021, 'Same. My appendectomy came with a separate bill from the radiologist I never met. The choice and consumer language around health care is a joke when you are unconscious.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210024, 101016, 'c79e547f-fba6-5ca8-8526-544205cea540', 210023, 'This is backwards. You already pay the tax, it is just called a premium and a deductible, and it goes up 12 percent a year. I would rather pay the government than a CEO whose bonus depends on denying my claim.', 'strongly_disagree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210027, 101017, '9452332e-b87a-548b-b5f8-588d7203f62e', 210026, 'NIH funds basic science, not the billion-dollar clinical trials that actually bring a drug to market. That last mile is private capital taking real risk, and price caps would kill exactly that investment.', 'disagree', 1, '2026-09-24 12:14:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210030, 101014, '232f8156-8be9-5077-abf7-b1377bbafed1', 210025, 'The small business angle is real, but both sides cherry-pick countries. Canada has waits, Germany has a mixed system people love, Singapore spends little with great outcomes. Maybe there is no single universal model to copy.', 'neutral', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210032, 101019, '4c972619-65e6-5a0b-be86-ef7edbf6c5ab', 210031, 'And the discrimination research is damning. When pay depends on customer bias, you have built bias into the wage structure. A base wage does not fix racism, but it stops subsidizing it.', 'agree', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210034, 101022, '11001984-a81c-5f63-9d57-22119137a664', 210033, 'Thank you. Nobody pushing abolition has ever worked a Friday night rush. They want to save us by cutting our pay in half and calling it progress.', 'strongly_agree', 6, '2026-09-24 13:59:24+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210037, 101023, 'b3d1f8fb-6aa7-5a0c-9dc6-c15cf2fa2c11', 210036, 'Raising the floor sounds nice until you realize enforcement is the actual problem. Wage theft in restaurants is rampant and the DOL barely inspects. A higher base wage at least shows up on the pay stub.', 'disagree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210040, 101024, 'f84ec808-4956-5e7c-8849-bad1fe689484', 210039, 'I have eaten at those places and the service is good, but the prices are 25 percent higher and I am still expected to tip on top half the time. The no-tip restaurant often just means hidden tip.', 'neutral', 5, '2026-09-24 13:25:45+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210042, 101025, 'b775819d-447b-5fbc-a57e-2a6565e13379', 210041, 'Exactly. Right now the rational move for a giant is to violate, pay, and repeat, because the fine is always smaller than the profit. Scaling the ceiling with revenue and repeat offenses flips that math.', 'strongly_agree', 0, '2026-09-23 20:22:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210044, 101026, '0b69664d-8df3-5463-8381-752528cfc3ad', 210043, 'But the GDPR tiers already account for severity, and regulators have discretion. Small companies are not getting 4 percent fines for minor issues. The fear outruns the actual enforcement pattern.', 'disagree', 8, '2026-09-23 23:14:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210045, 101025, '4ff27a04-8893-56ed-becd-a17274f513be', 210041, 'I like escalation in theory, but who decides what counts as a repeat offense? A company with 50 products will always have something in violation somewhere. You could escalate forever on technicalities.', 'neutral', 6, '2026-09-23 23:05:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210048, 101026, '101e8961-353e-53c6-bbab-3b72ff6e016f', 210046, 'That is a fair challenge, but fines fund the regulators and create the paper trail for bigger actions. It is not either-or: scale the fines and add the personal accountability on top.', 'neutral', 8, '2026-09-23 21:45:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210050, 101027, 'c995133a-0c49-5845-90c7-d2e8c0f01ed3', 210049, 'And Carpenter is the right anchor. The Court already said location history is special. The law treating it like a cookie banner violation is the mismatch.', 'agree', 3, '2026-09-23 22:01:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210052, 101028, 'd83da1dd-45fd-5db8-bec8-ef0f536973b4', 210051, 'If your business model cannot survive without quietly selling location, it should not survive. The small developer defense gets trotted out to protect brokers doing the actual selling.', 'disagree', 4, '2026-09-23 20:07:15+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210053, 101027, 'ffb4d8da-c5f4-5ec0-ba8f-b4c7b25af7b1', 210049, 'I agree the harm is real, but how do you price it? Is my grocery store trip worth the same as someone''s clinic visit? A flat payout feels arbitrary and a tiered one feels invasive to administer.', 'neutral', 8, '2026-09-24 00:32:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210056, 101028, 'be6993eb-cb2c-5d64-b4a9-3975597eaf9f', 210054, 'That seems like the reasonable middle: ban the sale, delete the data, and pay the victims from the penalty. The debate treats it as either-or when regulators can do both.', 'neutral', 6, '2026-09-23 19:28:15+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210059, 101006, '2914ba68-d865-5196-ad0d-893256c22cc9', 210058, 'Fair point that a label is cheap, but it has to be designed to survive the scroll. If it is tiny gray text nobody reads, it is decoration. Make it prominent or do not bother.', 'agree', 6, '2026-09-24 01:02:51+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210102, 101061, '2d536008-cfe6-5e5d-8112-4b1394eb3f5a', 210101, 'Feeling like a citizen is nice, but the studies on voting and recidivism show correlation, not proof. People who vote are already the ones getting jobs and staying clean; the ballot did not cause the turnaround. Let us not sell a feel-good story as crime policy.', 'disagree', 6, '2026-09-23 20:44:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210106, 101064, '9634b19f-6504-5eb4-9501-9508b05f23ed', 210105, 'Most of those fines and fees are not victim restitution, they are court costs, supervision fees, and interest that pile up precisely because the person cannot pay. Florida proved the point: people willing to vote stay barred over small surcharges. That is a poll tax with extra steps, and dressing it up as victim advocacy is dishonest.', 'strongly_disagree', 7, '2026-09-24 03:54:03+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210109, 101062, 'd193d39a-90f5-5315-8985-4ddd7f60f9b2', 210103, 'I agree the disparity is real and ugly. Where I get stuck is the remedy: automatic restoration helps future voters but does nothing for the policing and sentencing that created the 1-in-19 figure. It feels necessary and insufficient at the same time.', 'neutral', 0, '2026-09-24 04:37:44+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210112, 101067, '01016111-7c7d-5978-845d-676b6ce468a7', 210111, 'The 3.4% number is wealth growth divided by taxes paid, which is not a tax rate by any definition the code uses. Nobody''s rate is measured that way, including yours. If we are going to rewrite the tax code, let us at least be honest about the math we are using.', 'disagree', 4, '2026-09-23 21:51:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210115, 101070, '82d8950f-6db7-53cc-b1e2-7d3334c7b651', 210114, 'Thresholds always drift downward; the income tax started at 1% on the rich in 1913. And pay over several years just means selling the company slowly instead of quickly. A founder forced to divest to pay tax on value she has not received is still being punished for building something.', 'agree', 0, '2026-09-23 21:48:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210119, 101071, 'c4599b0a-6dbb-5079-b6bf-445005adc8f6', 210116, 'Courts do not strike down taxes because they are novel; they strike them down when they violate the text. A minimum tax on economic income has survived every serious challenge so far, and waiting for perfect legal certainty means waiting forever. The Court had its chance in Moore and blinked.', 'disagree', 0, '2026-09-23 15:36:45+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
